types:
[Node: {} as {
        events:
          | {
              type: 'FOO' | 'BAR';
              value: string;
            }
          | {
              type: 'OTHER';
            };
      }]

FOO.actions:
[Node: ({ event }) => {
            event.type satisfies 'FOO' | 'BAR'; // it could be narrowed down to `FOO` but it's not worth the effort/complexity
            event.value satisfies string;
            // @ts-expect-error
            event.value satisfies number;
          }]
